# Render the vignettes as the guide pages of the documentation site.
#
#   Rscript tools/render-guides.R
#
# Knits each vignette in vignettes/ to docs/guide/<page>.md, with the package
# installed from this checkout into a temporary library and the random seed
# set to 1 before each one, and writes its figures to docs/guide/figures/.
# Every page starts with a "Generated by tools/render-guides.R" comment.
#
# CI does not run this script, so its freshness check does not cover these
# pages: knitting runs the package's code and the packages the vignettes use,
# and the figures differ in their bytes from one platform to another. Run it
# after changing a vignette, or a function whose output a vignette prints,
# and commit the pages and figures it writes.

# Vignette -> page, in the order of the guide in mkdocs.yml.
guides <- c(
  using_heteroTests = "using-heterotests",
  tutorial = "tutorial",
  real_world_case_studies = "real-world-case-studies",
  statistical_theory_and_implementation = "statistical-theory-and-implementation",
  performance_comparison_guide = "performance-comparison-guide",
  comprehensive_guide = "comprehensive-guide",
  troubleshooting = "troubleshooting",
  bibliography = "bibliography"
)

out_dir <- file.path("docs", "guide")
fig_dir <- file.path(out_dir, "figures")

# Installed rather than loaded with pkgload::load_all(), so that a vignette
# sees the package as R CMD build shows it one: citation() reads the
# DESCRIPTION of an installed copy.
lib <- tempfile("render-guides-lib-")
dir.create(lib)
utils::install.packages(
  ".",
  lib = lib, repos = NULL, type = "source", quiet = TRUE,
  INSTALL_opts = "--no-docs"
)
.libPaths(c(lib, .libPaths()))
library(heteroTests, lib.loc = lib)

write_page <- function(lines, path) {
  con <- file(path, open = "wb")
  on.exit(close(con))
  writeLines(enc2utf8(lines), con, sep = "\n", useBytes = TRUE)
}

# Split a vignette into its title and its body, without the YAML header.
read_vignette <- function(path) {
  lines <- readLines(path, encoding = "UTF-8", warn = FALSE)
  fences <- which(lines == "---")
  if (length(fences) < 2L || fences[[1]] != 1L) {
    stop(path, " has no YAML header")
  }
  header <- lines[seq(2L, fences[[2]] - 1L)]
  title <- sub('^title:\\s*"?(.*?)"?\\s*$', "\\1", grep("^title:", header, value = TRUE))
  list(title = title, body = lines[-seq_len(fences[[2]])])
}

# Display maths written inside a paragraph, \[ on a line of its own, becomes a
# block of its own, which is what pymdownx.arithmatex recognises.
separate_display_maths <- function(lines) {
  out <- character()
  in_fence <- FALSE
  for (line in lines) {
    if (startsWith(line, "```")) in_fence <- !in_fence
    if (!in_fence && trimws(line) == "\\[") {
      out <- c(out, "", line)
    } else if (!in_fence && trimws(line) == "\\]") {
      out <- c(out, line, "")
    } else {
      out <- c(out, line)
    }
  }
  out
}

dir.create(fig_dir, showWarnings = FALSE, recursive = TRUE)
work_dir <- tempfile("render-guides-")
dir.create(work_dir)

for (vignette in names(guides)) {
  page <- guides[[vignette]]
  source_path <- file.path("vignettes", paste0(vignette, ".Rmd"))
  parsed <- read_vignette(source_path)

  input <- file.path(work_dir, paste0(page, ".Rmd"))
  writeLines(enc2utf8(parsed$body), input, useBytes = TRUE)
  unlink(list.files(fig_dir, pattern = paste0("^", page, "-"), full.names = TRUE))

  # The code runs from the root of the checkout; the figures are written under
  # docs/guide, and the page refers to them by a path relative to itself.
  knitr::opts_knit$set(root.dir = getwd(), base.dir = normalizePath(out_dir))
  knitr::opts_chunk$set(
    fig.path = paste0("figures/", page, "-"),
    dev = "png",
    dpi = 150,
    fig.width = 7.2,
    fig.height = 4.45
  )
  set.seed(1)
  output <- file.path(work_dir, paste0(page, ".md"))
  knitr::knit(input, output = output, quiet = TRUE, envir = new.env(parent = globalenv()))
  knitr::opts_chunk$restore()
  knitr::opts_knit$restore()

  # R pads printed output with trailing spaces, which do not show and which
  # `git diff --check` reports.
  body <- sub("[ \t]+$", "", readLines(output, encoding = "UTF-8", warn = FALSE))
  kept <- which(nzchar(body))
  body <- if (length(kept) == 0L) character() else body[min(kept):max(kept)]
  write_page(c(
    sprintf(
      "<!-- Generated by tools/render-guides.R from %s: do not edit by hand. -->",
      source_path
    ),
    "",
    paste("#", parsed$title),
    "",
    separate_display_maths(body)
  ), file.path(out_dir, paste0(page, ".md")))
  cat(file.path(out_dir, paste0(page, ".md")), "written from", source_path, "\n")
}

unlink(c(work_dir, lib), recursive = TRUE)
